"use client";
import { useTheme,type ThemePreference } from "./theme";
import { Icon,type IconName } from "./icons";
import { Badge,Button,SectionHeader } from "./ui";
import type { ProviderStatus } from "@/domain/email";
const themes:{value:ThemePreference;title:string;detail:string;icon:IconName}[]=[{value:"light",title:"Light",detail:"A bright, calm workspace",icon:"sun"},{value:"dark",title:"Dark",detail:"A softer evening view",icon:"moon"},{value:"system",title:"System",detail:"Follow your device",icon:"monitor"}];
export function SettingsPreview({geminiConfigured=false,emailProvider}:{geminiConfigured?:boolean;emailProvider:ProviderStatus}){
  const {preference,setPreference}=useTheme();
  return <div className="settings-stack"><section className="panel panel-padding"><SectionHeader title="Make yourself at home" description="Appearance is the only preference saved on this device." /><fieldset className="theme-fieldset"><legend className="sr-only">Visual theme</legend><div className="theme-options">{themes.map(theme=><label key={theme.value} className={"theme-option "+(preference===theme.value?"selected":"")}><input type="radio" name="theme" value={theme.value} checked={preference===theme.value} onChange={()=>setPreference(theme.value)} /><Icon name={theme.icon} /><strong>{theme.title}</strong><span className="muted small">{theme.detail}</span><span className="theme-check" aria-hidden="true">{preference===theme.value&&<Icon name="check" />}</span></label>)}</div></fieldset></section><section className="panel panel-padding"><SectionHeader title="Privacy, by intention" description="Active controls for the private workspace" /><div className="settings-row"><Icon name="shield" /><div><strong>Consent before AI processing</strong><p>Current scope permission is checked before every optional Gemini task. Both profiles must authorize a pair explanation.</p></div></div><div className="settings-row"><Icon name="lock" /><div><strong>Private contact details</strong><p>Encrypted contacts never enter matching DTOs or AI requests. Explanations send only factor numbers and temporary aliases.</p></div></div><div className="settings-row"><Icon name="profiles" /><div><strong>Human-led decisions</strong><p>Heuristic rankings need professional review. Match approval, exact email approval and dispatch are separate human decisions.</p></div></div></section><section className="panel panel-padding"><SectionHeader title="Connections & integrations" description="Gemini is optional. Deterministic matching and local search work without it." /><div className="integration-row"><span className="integration-icon"><Icon name="matches" /></span><div><strong>Gemini</strong><p className="muted small">Bounded search, pair explanations and permitted chat summaries</p></div><Badge>{geminiConfigured?"Optionally configured":"Unconfigured"}</Badge></div><div className="integration-row"><span className="integration-icon"><Icon name="mail" /></span><div><strong>Resend</strong><p className="muted small">Human-approved delivery; local drafts work without a provider</p></div><Badge>{emailProvider.ready?"Configured; live delivery unverified":"Sending unavailable"}</Badge></div><p className="muted small" id="integration-note">Provider credentials are configured privately by the operator through environment variables. Local drafting is active. Email sends require valid provider configuration, an unexpired exact approval and a separate human action. Internal chat saves encrypted conversations; proposed business changes require exact human confirmation.</p><Button variant="secondary" disabled aria-describedby="integration-note">Configure integrations unavailable</Button></section></div>;
}
